/**
 * @param {string} word
 * @return {number}
 */
var numberOfSpecialChars = function(word) {
    const lower = word.toLowerCase();
    const upper = word.toUpperCase();
    const seen = new Set();
    let res = 0;

    for (let i = 0; i < word.length; i++) {
        if ((word[i] === lower[i] && !seen.has(lower[i]) && seen.has(upper[i])) ||
            (word[i] === upper[i] && !seen.has(upper[i]) && seen.has(lower[i]))) {
            res++;
        }
        seen.add(word[i]);
    }

    return res;
};

/**
 * @param {string} word
 * @return {number}
 */
var numberOfSpecialChars = function(word) {
    const arr = new Array(52).fill(0);
    let res = 0;

    for (let i = 0; i < word.length; i++) {
        const code = word.charCodeAt(i);
        const pos = code - (code >= 97 ? 71 : 65);

        if (arr[pos] === 0 && arr[(pos + 26) % 52] > 0) {
            res++;
        }

        arr[pos]++;
    }

    return res;
};

