var numberOfSpecialChars = function(word) {
    const set = new Set(word);
    let res = 0;

    for (let i = 0; i < 26; i++) {
        const lower = String.fromCharCode(65 + i);
        const upper = String.fromCharCode(97 + i);

        if (set.has(lower) && set.has(upper)) {
            res++;
        }
    }

    return res;
};

